import { Component, OnInit } from '@angular/core';
import { Location } from '@angular/common';

import { ProductosService } from "../services/productos.service";
import { environment } from '../../environments/environment'


import { Router } from '@angular/router';
import { UsuariosService } from '../services/usuarios.service';
export interface Producto{
  id: number,
  nombre: string,
  marca: string,
  categoria: string,
  stock: number,
  valor_energetico: Float32Array,
  grasas: Float32Array,
  grasas_saturadas: Float32Array,
  hidratos_carbono: Float32Array,
  azucares: Float32Array,
  fibra: Float32Array,
  proteina: Float32Array,
  sal: Float32Array,
  precio_kg: Float32Array,
  ingerdientes: string,
  foto: string,
  precio: Float32Array,
  enListaCompra: boolean,
  cantidad: number,
  idLista: string,
}

export interface ListaCompra{
  id: string,
  idUsu: string,
  idProd: number,
  fecha: string | null,
  cantidad: number,
}
@Component({
  selector: 'app-pagina-buscador',
  templateUrl: './pagina-buscador.page.html',
  styleUrls: ['./pagina-buscador.page.scss'],
})
export class PaginaBuscadorPage {
  imgUrl = '';

  productos: Producto [] = [];
  
  listaCompra: ListaCompra [] = [];

  valueBusquedaInput = '';

  private idUsu: string = '';
  

  constructor(private location: Location, private productosService: ProductosService, private router: Router) { }

  ngOnInit(): void {
    this.getUsuarioLog();
    this.getListaCompraUsu();
  }

  volverAtras() {
    this.location.back();
  }



  getUsuarioLog() {
    const idUsuario = localStorage.getItem('idUsuario');
    
    if (idUsuario !== null) {
      this.idUsu = idUsuario;
      console.log('El usuario logueado es: '+ this.idUsu);
    } else {
      console.error('El valor de idUsuario en localStorage es nulo.');
    }
  }




  cambiaPag(idProd: number): void {
    let url = '/pagina-producto/' + idProd;
    this.router.navigate([url]);
  }


  cantidadProducto: number = 1;


  incrementar(producto: any){
    producto.cantidad++;
      console.log('Nueva cantidad = ' +  producto.cantidad)
      this.actualizarCantidad(producto.id, producto.cantidad, producto.idLista) 
  }

  decrementar(producto: any){
    if (producto.cantidad > 1){
      producto.cantidad--;
    console.log('Nueva cantidad = ' +  producto.cantidad)
    this.actualizarCantidad(producto.id, producto.cantidad, producto.idLista) 
    }else{
      console.log('Solo queda una');
    }
  }

  eliminar(producto: any){
    producto.enListaCompra = false;
    this.borrarProd(producto.idLista);
  }

  anadirProducto(producto: any){
    const fechaActual = new Date().toISOString().split('T')[0];
    const body = {
      idUsu: this.idUsu,
      idProd: producto.id,
      fecha: fechaActual, 
      cantidad: 1
    };
    this.productosService.postListaCompra(body )
    .subscribe((result) => {
      console.log(result);
    })
    this.compararListaBusqueda();
    producto.enListaCompra = true;
    
  }


  getBusquedaProducto() {
    this.productosService.getBusquedaProducto(this.valueBusquedaInput)
      .subscribe(res => {
        this.productos = res.productos;
        console.log(this.productos.idProd);
        this.imgUrl = `${environment.baseUrl}/uploads/fotoproducto/`+res.productos.foto;
        this.compararListaBusqueda();
      });

      
  }
  getListaCompraUsu() {
    this.productosService.getListaCompra(this.idUsu).subscribe((result) => {
      if (result.listacompra) {
        this.listaCompra = result.listacompra.map((item: ListaCompra) => 
        ({ idProd: item.idProd, 
          cantidad: item.cantidad, 
          id: item.id
        }));
  
        console.log(this.listaCompra);
      } 
    });
  }

  compararListaBusqueda(){
    this.listaCompra.forEach((productoCompra) => {
      const productoEncontrado = this.productos.find((producto) => productoCompra.idProd === producto.id);
      if (productoEncontrado) {
        productoEncontrado.enListaCompra = true;
        productoEncontrado.cantidad = productoCompra.cantidad;
        productoEncontrado.idLista = productoCompra.id;
        //console.log(`Producto con id ${productoEncontrado.id} está en la lista y su cantidad es ${productoEncontrado.cantidad}`);
      } else {
       // console.log(`No se encontró el producto con idProd ${productoCompra.idProd} en la lista de productos`);
      }
    });
  }

  borrarProd(idLista: string){
    this.productosService.deleteListaCompra(idLista).subscribe((result) =>{
      //this.getProductos(); //Recarga la lista de productos
    });
  }


  actualizarCantidad(idProd: string, nuevaCantidad: number, idLista: string) {
    const fechaActual = new Date().toISOString().split('T')[0];
    const body = {
      idUsu: this.idUsu,
      idProd: idProd,
      fecha: fechaActual, 
      cantidad: nuevaCantidad
    };

    console.log('Cuerpo de la solicitud:', body);

    this.productosService.putListaCompra(idLista, body)
      .subscribe(
        (res) => {
          console.log('Respuesta correcta:', res);
        },
        (error) => {
          console.error('Error en la solicitud PUT: again', error);
        }
      );
  }

}


<ion-content>
    <ion-header collapse="condense" class="custom-header">
        <ion-toolbar class="custom-toolbar">
          <button class="volver-atras" [routerLink]="['/tabs/tab1']">
            <ion-icon name="chevron-back-outline"></ion-icon>
            Volver atrás</button>
        </ion-toolbar>
      </ion-header>
      
      <div class="divSearch">
        <form autocomplete="off" id="busqueda" (ngSubmit)="getBusquedaProducto()">
            <input type="text" name="search" id="search" placeholder="Busca tus productos aquí" [(ngModel)]="valueBusquedaInput" ngModel>
            <button>
              <span> <ion-icon class="lupa" name="search-outline"> </ion-icon></span>
            </button>
        </form>
      </div>

      <div *ngFor="let producto of productos" class="producto-container">
        <div class="navegador-producto" (click)="cambiaPag(producto.id)"> <!--[routerLink]="['/pagina-producto', producto.idProd]"-->
          <img [src]="imgUrl" alt="Product Image" />
          <div class="product-text">
            <h3>{{producto.nombre}}</h3>
            <p> {{ producto.precio }}€</p>
          </div>
        </div>
      
        <div class="product-buttons">
          <button *ngIf="!producto.enListaCompra"  (click)="anadirProducto(producto)"class="add">Añadir
            <ion-icon class="add-button" name="add-circle-outline"></ion-icon>
          </button>
          <div *ngIf="producto.enListaCompra" class="add2">
            <button (click)="decrementar(producto)">
              <ion-icon class="add-button" name="remove-circle-outline"></ion-icon>
            </button>
            <span>{{ producto.cantidad }}</span>
            <button (click)="incrementar(producto)">
              <ion-icon class="add-button" name="add-circle-outline"></ion-icon>
            </button>
            <button (click)="eliminar(producto);">
              <ion-icon class="add-button" name="trash-outline"></ion-icon>
            </button>
          </div>
        </div>
      </div>

      <div class="menu-inferior">
        <button [routerLink]="['/tabs/tab1']">
          <ion-icon class="icono-menu" name="list-circle-outline"></ion-icon>
        </button>
        <button [routerLink]="['/tabs/tab2']">
          <ion-icon class="icono-menu" name="chatbubbles-outline"></ion-icon>
        </button>
        <button [routerLink]="['/tabs/tab3']">
          <ion-icon class="icono-menu" name="person-circle-outline"></ion-icon>
        </button>
      </div>
</ion-content>
